'use strict';

// MODULES //

var abs = require( '@stdlib/math/base/special/abs' );
var abs2 = require( '@stdlib/math/base/special/abs2' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );


// VARIABLES //

var GAM = 4096.0;
var GAM_SQ = abs2( GAM );
var RGAM_SQ = abs2( 1.0 / GAM );


// MAIN //

/**
* Construct the parameters for a modified Givens plane rotation.
*
* @param {number} d1 - scaling factor for the first vector component
* @param {number} d2 - scaling factor for the second vector component
* @param {number} x1 - first component of the first vector
* @param {number} y1 - first component of the second vector
* @param {Float64Array} param - output array
* @param {integer} stride - index increment
* @param {NonNegativeInteger} offset - starting index
* @returns {Float64Array} - output array
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var out = drotmg( 3.0, 4.0, 1.5, 2.5, new Float64Array( 5 ), 1, 0 );
* // returns <Float64Array>[ 1.0, 0.45, 0.0, 0.0, 0.6 ]
*/
function drotmg( d1, d2, x1, y1, param, stride, offset ) {
	var flag;
	var temp;
	var ad1;
	var ad2;
	var h11;
	var h12;
	var h21;
	var h22;
	var p1;
	var p2;
	var q1;
	var q2;
	var u;

	h11 = 1.0;
	h12 = 0.0;
	h21 = 0.0;
	h22 = 1.0;
	if ( isnan( d1 ) || isnan( d2 ) || isnan( x1 ) || isnan( y1 ) ) {
		param[ offset ] = NaN;
		param[ offset + stride ] = NaN;
		param[ offset + ( 2 * stride ) ] = NaN;
		param[ offset + ( 3 * stride ) ] = NaN;
		param[ offset + ( 4 * stride ) ] = NaN;
		return param;
	}

	if ( d1 < 0.0 ) {
		flag = -1.0;
		h11 = 0.0;
		h12 = 0.0;
		h21 = 0.0;
		h22 = 0.0;
		d1 = 0.0;
		d2 = 0.0;
		x1 = 0.0;
	} else {
		p2 = d2 * y1;
		if ( p2 === 0.0 ) {
			flag = -2.0;
			param[ offset ] = flag;
			return param;
		}
		p1 = d1 * x1;
		q2 = p2 * y1;
		q1 = p1 * x1;
		ad1 = abs( q1 );
		ad2 = abs( q2 );

		if ( ad1 > ad2 ) {
			h21 = -y1 / x1;
			h12 = p2 / p1;
			u = 1 - ( h12 * h21 );
			if ( u > 0.0 ) {
				flag = 0.0;
				d1 /= u;
				d2 /= u;
				x1 *= u;
			} else {
				flag = -1.0;
				h11 = 0.0;
				h12 = 0.0;
				h21 = 0.0;
				h22 = 0.0;
				d1 = 0.0;
				d2 = 0.0;
				x1 = 0.0;
			}
		}
		if ( q2 < 0.0 || q1 < 0.0 ) {
			flag = -1.0;
			h11 = 0.0;
			h12 = 0.0;
			h21 = 0.0;
			h22 = 0.0;
			d1 = 0.0;
			d2 = 0.0;
			x1 = 0.0;
		} else {
			flag = 1.0;
			h11 = p1 / p2;
			h22 = x1 / y1;
			u = 1 + ( h11 * h22 );
			temp = d2 / u;
			d2 = d1 / u;
			d1 = temp;
			x1 = y1 * u;
		}

		if ( d1 !== 0.0 ) {
			while ( ( d1 < RGAM_SQ ) || ( d1 > GAM_SQ ) ) {
				if ( flag === 0.0 ) {
					flag = -1.0;
					h11 = 1.0;
					h22 = 1.0;
				} else {
					flag = -1.0;
					h21 = -1.0;
					h12 = 1.0;
				}
				if ( d1 < RGAM_SQ ) {
					d1 *= GAM_SQ;
					x1 /= GAM;
					h11 /= GAM;
					h12 /= GAM;
				} else {
					d1 /= GAM_SQ;
					x1 *= GAM;
					h11 *= GAM;
					h12 *= GAM;
				}
			}
		}

		if ( d2 !== 0.0 ) {
			while ( ( abs( d2 ) < RGAM_SQ ) || ( abs( d2 ) > GAM_SQ ) ) {
				if ( abs(d2) < RGAM_SQ ) {
					d2 *= GAM_SQ;
					h21 /= GAM;
					h22 /= GAM;
				} else {
					d2 /= GAM_SQ;
					h21 *= GAM;
					h22 *= GAM;
				}
			}
		}
	}

	param[ offset ] = flag;

	if ( flag < 0.0 ) {
		param[ offset + stride ] = h11;
		param[ offset + ( 2 * stride ) ] = h21;
		param[ offset + ( 3 * stride ) ] = h12;
		param[ offset + ( 4 * stride ) ] = h22;
	} else if ( flag === 0.0 ) {
		param[ offset + ( 2 * stride ) ] = h21;
		param[ offset + ( 3 * stride ) ] = h12;
	} else {
		param[ offset + stride ] = h11;
		param[ offset + ( 4 * stride ) ] = h22;
	}

	return param;
}


// EXPORTS //

module.exports = drotmg;
